/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let tabName = '';
	let tabTitle = api.state.selectedTabTitle;
	tabName = tabTitle + '';

	return {
		event: 'Manual CI Creation: Process cancelled',
		value: {
			'Tab name': tabName
		}
	};

}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		params: {
			'classHierarchy': null
		}
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const {
		id: table
	} = api.state.dependencyState.selectedDependentObj;
	return {
		propName: 'refPickerProps',
		value: {
			table,
			fixedFilter: '',
			query: 'ORDERBYsys_id',
			requestingEvent: {
				elementId: 'dependent_ci_typeahead'
			}
		}
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	//Reporting the event will add to the total click count, so no value is needed
	return {
		event: 'Manual CI Creation: Add new relationship',
		value: {}
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const {
		relProps
	} = api.state;
	const { rowSelectionObj } = relProps;
	const {
		selectedRows
	} = event.payload;
	relProps.rowDefinitions.rows.forEach((row) => {
		if(selectedRows.hasOwnProperty(row.key)) {
			row.isSelected = true;
		} else {
			delete rowSelectionObj[row.key];
		}
	});
	return {
		propName: 'relProps',
		value: {
			...relProps,
			rowSelectionObj: {
				...rowSelectionObj,
				...selectedRows
			}
		}
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
