}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let selectedTab = api.state.selectedTabId;
	if(selectedTab == "relationship_definition"){
		let rels = api.state.relProps.relationships;
		let relCount  = rels.length;
		return {
			event: 'Manual CI Creation: Relation definition completed',
			value: {
				'Relationship Count': relCount
			}
		};
	} else {
		return {
			event: null,
			value: null
		};
	}
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {

	let table = api.state.mainTable;
	let opStatus = api.state.userPayload.attributes[table].fields["operational_status"]?.value || null;

	let rules = api.state.selectedRules;
	let ruleCount = Object.keys(rules).length;

	return {
		event: 'Manual CI Creation: New CI saved',
		value: {
			'Operational Status': opStatus,
			'Rule Count': ruleCount
		}
	};
}

