/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let {
		listControllerSortApplied,
		relProps
	} = api.state;
	var cbEncodedQueryValue = relProps.cbEncodedQuery.value;

	if (!listControllerSortApplied) {
		cbEncodedQueryValue = (cbEncodedQueryValue != null && cbEncodedQueryValue != "") ? cbEncodedQueryValue + "^ORDERBYsys_id" : "=ORDERBYsys_id";
	}

	return {
		encodedQuery: cbEncodedQueryValue
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		event: 'Manual CI Creation: Cancel new relationship creation',
		value: {}
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const {
		dependencyState: {
			dependencies
		},
		relProps: {
			relTypeSelectedItem,
			relationships
		}
	} = api.state;
	const { selectionProps, current: { table, query } } = api.data.list_controller;
	const { sysClassName } = api.context.props;
	const { isParent, id, relName, type } = relTypeSelectedItem;
	const splitId = id.split(':');
	const relTypeSysId = splitId[splitId.length - 1];
	let relTypeObj = {
		isParent,
		relName,
		relTypeSysId,
		relTable: type
	};
	let payload = {
		relTypeObj,
		listProps: {
			selectionProps,
			table,
			query
		},
		currentRels: relationships,
		classInfo: {
			sysClassName,
			dependencies
		}
	};
	return {
		payload
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	let { hideRelTypes, relTypeSelectedItem } = api.state.relProps;
	const { value } = event.payload;
	if (value == true && relTypeSelectedItem && relTypeSelectedItem.type == 'cmdb_rel_ci') {
		relTypeSelectedItem = {};
	}
	return {
		propName: 'relProps',
		value: {
			...api.state.relProps,
			relTypeSelectedItem: relTypeSelectedItem,
			hideRelTypes: {
				...hideRelTypes,
				ci: value
			}
		}
	};
}

